SELECT json_get_str(j, 'commit', 'collection') AS event, COUNT(*) AS count FROM bluesky GROUP BY event ORDER BY count DESC;
SELECT json_get_str(j, 'commit', 'collection') AS event, COUNT(*) AS count, COUNT(DISTINCT json_get_str(j, 'did')) AS users FROM bluesky WHERE json_get_str(j, 'kind') = 'commit' AND json_get_str(j, 'commit', 'operation') = 'create' GROUP BY event ORDER BY count DESC;
SELECT event, EXTRACT(HOUR FROM to_timestamp_micros(time_us)) AS hour_of_day, COUNT(*) AS count FROM (SELECT json_get_str(j, 'commit', 'collection') AS event, json_get_int(j, 'time_us') AS time_us FROM bluesky WHERE json_get_str(j, 'kind') = 'commit' AND json_get_str(j, 'commit', 'operation') = 'create') WHERE event IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT json_get_str(j, 'did') AS user_id, to_timestamp_micros(MIN(json_get_int(j, 'time_us'))) AS first_post_date FROM bluesky WHERE json_get_str(j, 'kind') = 'commit' AND json_get_str(j, 'commit', 'operation') = 'create' AND json_get_str(j, 'commit', 'collection') = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_date ASC NULLS LAST LIMIT 3;
SELECT json_get_str(j, 'did') AS user_id, (MAX(json_get_int(j, 'time_us')) - MIN(json_get_int(j, 'time_us'))) / 1000 AS activity_span FROM bluesky WHERE json_get_str(j, 'kind') = 'commit' AND json_get_str(j, 'commit', 'operation') = 'create' AND json_get_str(j, 'commit', 'collection') = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC NULLS LAST LIMIT 3;
